(async () => {
  const origFetch = window.fetch;
  const calls = [];
  window.fetch = async (url, opts = {}) => {
    calls.push({ url: String(url), method: opts.method || 'GET', body: opts.body || null });
    return new Response(JSON.stringify({
      ok: true, seen: true, seen_date: '2026-09-07',
      url: 'https://example.test/job', country: 'uk', company: 'Acme',
    }), { status: 200, headers: { 'Content-Type': 'application/json' } });
  };
  try {
    const card = document.createElement('position-card');
    document.body.appendChild(card);
    card.job = {
      title: 'Staff Engineer',
      url: '#job-title-seen-test',
      country: 'uk',
      company: 'Acme',
      idempotency_key: 'abc123',
      seen: false,
    };
    const title = card.querySelector('.job-title');
    if (!title) {
      card.remove();
      return { ok: false, error: 'no job-title' };
    }
    title.addEventListener('click', (e) => e.preventDefault(), true);
    title.click();
    await new Promise((r) => setTimeout(r, 50));
    const inner = card.querySelector('.position-card');
    const seenBtn = card.querySelector('.saw-before-btn');
    const result = {
      ok: true,
      scriptSrc: [...document.querySelectorAll('script')].map(s => s.src).find(s => s.includes('position-card')),
      fetchCalls: calls,
      hasPositionSeen: inner?.classList.contains('position-seen') || false,
      seenBtnActive: seenBtn?.classList.contains('active') || false,
      seenBtnPressed: seenBtn?.getAttribute('aria-pressed') || null,
      jobSeen: !!card.job?.seen,
    };
    // second click should not POST again
    title.click();
    await new Promise((r) => setTimeout(r, 50));
    result.fetchCallsAfterSecondClick = calls.length;
    card.remove();
    return result;
  } finally {
    window.fetch = origFetch;
  }
})()

(async () => {
  const origFetch = window.fetch;
  const calls = [];
  window.fetch = async (url, opts = {}) => {
    const body = opts.body ? JSON.parse(opts.body) : null;
    calls.push(body);
    const seen = body?.seen !== false;
    return new Response(JSON.stringify({
      ok: true, seen, seen_date: seen ? '2026-09-07' : '',
      url: 'https://example.test/job', country: 'uk', company: 'Acme',
    }), { status: 200, headers: { 'Content-Type': 'application/json' } });
  };
  try {
    const card = document.createElement('position-card');
    document.body.appendChild(card);
    card.job = {
      title: 'Staff Engineer', url: '#toggle-seen-test',
      country: 'uk', company: 'Acme', idempotency_key: 'abc123', seen: false,
    };
    const more = card.querySelector('.position-more-btn');
    more?.click();
    const btn = card.querySelector('.saw-before-btn');
    btn.click();
    await new Promise((r) => setTimeout(r, 50));
    const afterMark = {
      seen: !!card.job?.seen,
      class: card.querySelector('.position-card')?.classList.contains('position-seen'),
      payload: calls[0],
    };
    const btn2 = card.querySelector('.saw-before-btn');
    btn2.click();
    await new Promise((r) => setTimeout(r, 50));
    const afterClear = {
      seen: !!card.job?.seen,
      class: card.querySelector('.position-card')?.classList.contains('position-seen'),
      payload: calls[1],
    };
    card.remove();
    return { afterMark, afterClear, callCount: calls.length };
  } finally {
    window.fetch = origFetch;
  }
})()
